// Convierte la salida del agente en el contrato que espera el front:
// { output, steps, sources, suggestions, razonamiento, mode, sessionId }
const item = $input.first().json;
let output = (item.output ?? item.text ?? '').toString();
output = output.replace(/<think>[\s\S]*?<\/think>/gi, '').trim();
if (/^\s*Calling\s+\w+\s+with\s+input/i.test(output)) {
  output = 'No logré consultar la base de conocimiento en este intento. ¿Puedes repetir la pregunta o pulsar «Nueva» para empezar otra conversación?';
}

// Bloque pitwall-meta (razonamiento + sugerencias). Tolerante a JSON imperfecto de modelos locales.
const parseMeta = (txt) => {
  let meta = { razonamiento: '', sugerencias: [] };
  let m = txt.match(/```\s*pitwall-meta\s*([\s\S]*?)```/i) || txt.match(/```\s*(?:json)?\s*(\{[\s\S]*?"sugerencias"[\s\S]*?\})\s*```/i);
  if (!m) return { meta, cleaned: txt };
  const body = m[1];
  try { meta = { ...meta, ...JSON.parse(body) }; }
  catch (e) {
    const r = body.match(/"razonamiento"\s*:\s*"((?:[^"\\]|\\.)*)"/);
    if (r) meta.razonamiento = r[1];
    const s = body.match(/"sugerencias"\s*:\s*\[([\s\S]*?)\]/);
    if (s) meta.sugerencias = [...s[1].matchAll(/"((?:[^"\\]|\\.)*)"/g)].map(x => x[1]);
  }
  return { meta, cleaned: txt.replace(m[0], '').trim() };
};
const parsed = parseMeta(output);
let meta = parsed.meta;
output = parsed.cleaned;

// 2) Pasos intermedios reales: qué buscó y qué encontró
const parseMaybe = (v) => { if (typeof v !== 'string') return v; try { return JSON.parse(v); } catch (e) { return v; } };
// La herramienta de Qdrant devuelve: [{ response: [{ type: 'text', text: '{"pageContent":..., "metadata":{...}}' }, ...] }]
const extractDocs = (obs) => {
  let o = parseMaybe(obs);
  const out = [];
  const visit = (x) => {
    if (x == null) return;
    if (Array.isArray(x)) { x.forEach(visit); return; }
    if (typeof x === 'string') { const p = parseMaybe(x); if (p !== x) visit(p); return; }
    if (typeof x === 'object') {
      if (Array.isArray(x.response)) { visit(x.response); return; }
      if (typeof x.text === 'string' && x.type === 'text') { visit(x.text); return; }
      if ('pageContent' in x || 'metadata' in x) { out.push({ pageContent: x.pageContent || '', metadata: x.metadata || {} }); return; }
    }
  };
  visit(o);
  return out;
};

const steps = [];
const sources = [];
const contexto = [];
const seen = new Set();
// Etiqueta legible de una fuente: "Documento · Art. X (pág. N)" o solo el título de la guía
const etiqueta = (src) => src.documento + (src.articulo ? ' · Art. ' + src.articulo : '') + (src.pagina ? ' (pág. ' + src.pagina + ')' : '');
const registrar = (src, texto) => {
  const key = src.documento + '|' + src.articulo;
  if (seen.has(key)) return false;
  seen.add(key);
  sources.push(src);
  contexto.push({ ref: src.documento + (src.articulo ? ' · Art. ' + src.articulo : ''), texto });
  return true;
};
const pasoFuentes = (nuevas) => {
  if (nuevas.length === 0) {
    steps.push({ tipo: 'herramienta', titulo: 'No encontró información sobre este tema en los documentos', detalle: '' });
    return;
  }
  steps.push({ tipo: 'herramienta', titulo: nuevas.length === 1 ? 'Consultó 1 fuente' : `Consultó ${nuevas.length} fuentes`, detalle: nuevas.map(etiqueta).join(' | ') });
};

// Búsqueda hecha antes de que el agente respondiera
let pre = {};
try { pre = $('Armar contexto').first().json || {}; } catch (e) {}
if (pre.consulta) {
  steps.push({ tipo: 'busqueda', titulo: 'Buscó en los documentos oficiales', detalle: pre.consulta });
  const nuevas = [];
  for (const cx of (pre.contexto || [])) {
    if (registrar(cx.source, cx.texto)) nuevas.push(cx.source);
  }
  pasoFuentes(nuevas);
}
// Búsquedas adicionales que el agente decidió hacer con la herramienta
for (const s of (item.intermediateSteps || [])) {
  const action = s.action || {};
  const ti = action.toolInput;
  const q = typeof ti === 'string' ? ti : (ti?.input ?? ti?.query ?? JSON.stringify(ti ?? ''));
  steps.push({ tipo: 'busqueda', titulo: 'Amplió la búsqueda', detalle: q });
  const nuevas = [];
  for (const dDoc of extractDocs(s.observation)) {
    const md = dDoc.metadata || {};
    const text = (dDoc.pageContent || '').toString();
    const src = { documento: md.documento || md.titulo || md.fuente || 'Base de conocimiento', articulo: md.articulo || md.subtipo || '', titulo: md.titulo_articulo || md.titulo || '', pagina: md.pagina || '', url: md.url || '', tipo: md.tipo || '', extracto: text.slice(0, 240) };
    if (registrar(src, text.slice(0, 1800))) nuevas.push(src);
  }
  if (nuevas.length) pasoFuentes(nuevas);
}
if (meta.razonamiento) steps.push({ tipo: 'razonamiento', titulo: 'En qué se basó', detalle: meta.razonamiento });

// Si el modelo no entregó sugerencias, se ofrecen preguntas de arranque sobre la F1 2026
const SUGERENCIAS_BASE = ['¿Qué cambió en la F1 en 2026?', '¿Quién va ganando el campeonato?', '¿Cómo funciona un fin de semana con sprint?', '¿Qué es el Overtake Mode?'];
let sugerencias = Array.isArray(meta.sugerencias) ? meta.sugerencias.map(String).filter(s => s.trim()).slice(0, 4) : [];
if (sugerencias.length === 0) sugerencias = SUGERENCIAS_BASE.slice(0, 3);
// El panel "Cómo llegué a esta respuesta" muestra solo las fuentes consultadas: una línea por documento con sus artículos y páginas
const porDocumento = new Map();
for (const s of sources) {
  const g = porDocumento.get(s.documento) || { tipo: s.tipo, articulos: [], paginas: [] };
  if (s.articulo && !g.articulos.includes(s.articulo)) g.articulos.push(s.articulo);
  if (s.pagina && !g.paginas.includes(s.pagina)) g.paginas.push(s.pagina);
  porDocumento.set(s.documento, g);
}
const listar = (arr, sing, plur) => arr.length === 0 ? '' : (arr.length === 1 ? sing + ' ' + arr[0] : plur + ' ' + arr.slice(0, -1).join(', ') + ' y ' + arr[arr.length - 1]);
const pasosFuentes = [];
for (const [documento, g] of porDocumento) {
  let detalle = listar(g.articulos, 'Artículo', 'Artículos');
  const pags = listar(g.paginas, 'página', 'páginas');
  if (pags) detalle += (detalle ? ' · ' : '') + pags;
  if (!detalle) detalle = g.tipo === 'guia' ? 'Guía en español de PitWall' : (g.tipo === 'temporada' ? 'Datos oficiales de la temporada 2026' : (g.tipo === 'temporada_narrativa' ? 'Resumen de la temporada 2026' : ''));
  pasosFuentes.push({ tipo: 'busqueda', titulo: documento, detalle });
}
if (pasosFuentes.length === 0) pasosFuentes.push({ tipo: 'busqueda', titulo: 'No hizo falta consultar los documentos', detalle: '' });
steps.length = 0;
steps.push(...pasosFuentes);
let sessionId = '';
try { sessionId = $('Cuando llega un mensaje').first().json.sessionId || ''; } catch (e) {}

return [{ json: {
  output,
  steps,
  sources,
  suggestions: sugerencias,
  razonamiento: meta.razonamiento || '',
  mode: 'rag',
  sessionId,
  contexto,
  prompt_evaluador: 'RESPUESTA DEL ASISTENTE:' + String.fromCharCode(10) + output + String.fromCharCode(10) + String.fromCharCode(10) + 'FRAGMENTOS RECUPERADOS DE LA BASE DE CONOCIMIENTO (texto completo):' + String.fromCharCode(10) + (contexto.length ? contexto.map((c, i) => '[' + (i + 1) + '] ' + c.ref + String.fromCharCode(10) + c.texto).join(String.fromCharCode(10) + String.fromCharCode(10)) : '(no se recuperó ningún fragmento)')
} }];

// Une el veredicto del evaluador con la respuesta ya formateada
const base = $('Formatear respuesta').first().json;
// Con Ollama en modo JSON el nodo ya entrega el objeto parseado; si no, viene como texto.
const ev = $input.first().json;
let evaluacion = { fundamentada: null, confianza: null, comentario: 'El evaluador no respondió' };
if (ev && typeof ev === 'object' && 'fundamentada' in ev) {
  evaluacion = { ...evaluacion, ...ev };
} else {
  let raw = ev.text ?? ev.output ?? '';
  if (raw && typeof raw === 'object') raw = JSON.stringify(raw);
  raw = String(raw).replace(/<think>[\s\S]*?<\/think>/gi, '').trim();
  const m = raw.match(/\{[\s\S]*\}/);
  if (m) { try { evaluacion = { ...evaluacion, ...JSON.parse(m[0]) }; } catch (e) {} }
}
if (typeof evaluacion.fundamentada === 'string') evaluacion.fundamentada = evaluacion.fundamentada.toLowerCase() === 'true';
if (typeof evaluacion.confianza === 'string') evaluacion.confianza = parseFloat(evaluacion.confianza) || null;
// Regla determinista: saludos, aclaraciones y rechazos de temas ajenos (sin consultar la base y sin cifras) no tienen nada que verificar.
const sinFragmentos = !Array.isArray(base.contexto) || base.contexto.length === 0;
const sinCifras = !/\d/.test(String(base.output || '').replace(/f[óo]rmula\s*(uno|1)|\bF1\b|\b2026\b/gi, ''));
if (sinFragmentos && sinCifras) {
  evaluacion = { fundamentada: true, confianza: 1, comentario: 'Sin afirmaciones que verificar' };
}
const steps = [...(base.steps || [])];
if (evaluacion.fundamentada === true) {
  steps.push({ tipo: 'evaluacion', titulo: 'Verificado: la respuesta está respaldada por las fuentes', detalle: evaluacion.comentario || '' });
} else if (evaluacion.fundamentada === false) {
  steps.push({ tipo: 'evaluacion', titulo: 'Atención: hay afirmaciones que no aparecen en las fuentes', detalle: evaluacion.comentario || '' });
}
const { contexto, prompt_evaluador, ...limpio } = base;
return [{ json: { ...limpio, steps, evaluacion } }];

// Arma el prompt para convertir la última pregunta en una consulta de búsqueda autónoma
const trigger = $('Cuando llega un mensaje').first().json;
const chatInput = String(trigger.chatInput ?? '').trim();
const sessionId = trigger.sessionId ?? '';
const grupos = ($input.first().json.messages || []).slice(-3);
const historial = grupos.map(g => (g.human ? 'Usuario: ' + String(g.human).slice(0, 400) : '') + (g.ai ? '\nAsistente: ' + String(g.ai).replace(/```[\s\S]*?```/g, '').slice(0, 400) : '')).join('\n');
const hayHistorial = grupos.length > 0;
const prompt_reformular = 'HISTORIAL RECIENTE:\n' + (historial || '(vacío)') + '\n\nÚLTIMA PREGUNTA DEL USUARIO:\n' + chatInput + '\n\nCONSULTA DE BÚSQUEDA:';
return [{ json: { chatInput, sessionId, hayHistorial, prompt_reformular } }];

// Normaliza la consulta (venga del reformulador o directa) y conserva chatInput/sessionId
const base = $('Preparar reformulación').first().json;
const item = $input.first().json || {};
let consulta = '';
if (typeof item.text === 'string') consulta = item.text;
else if (typeof item.output === 'string') consulta = item.output;
consulta = consulta.replace(/<think>[\s\S]*?<\/think>/gi, '').replace(/^CONSULTA DE BÚSQUEDA:\s*/i, '').replace(/["“”`]/g, '').split('\n').map(s => s.trim()).filter(Boolean)[0] || '';
if (!consulta || consulta.length > 200) consulta = base.chatInput;
return [{ json: { chatInput: base.chatInput, sessionId: base.sessionId, consulta } }];

// Reúne los fragmentos recuperados en un contexto para el agente y en fuentes/pasos para el front
const q = $('Armar consulta').first().json;
const contexto = [];
const seen = new Set();
for (const it of $input.all()) {
  const j = it.json || {};
  const doc = j.document || j;
  const text = String(doc.pageContent ?? j.pageContent ?? '').trim();
  if (!text) continue;
  const md = doc.metadata || j.metadata || {};
  const documento = md.documento || md.titulo || md.fuente || 'Fragmento de la base';
  const articulo = md.articulo || md.subtipo || '';
  const key = documento + '|' + articulo + '|' + (md.parte || '');
  if (seen.has(key)) continue;
  seen.add(key);
  contexto.push({ ref: documento + (articulo ? ' · Art. ' + articulo : ''), texto: text.slice(0, 850), score: j.score ?? null,
    source: { documento, articulo, titulo: md.titulo_articulo || md.titulo || '', pagina: md.pagina || '', url: md.url || '', tipo: md.tipo || '', extracto: text.slice(0, 240) } });
}
const contexto_texto = contexto.length
  ? contexto.map((c, i) => '[' + (i + 1) + '] ' + c.ref + '\n' + c.texto).join('\n\n')
  : '(no se encontraron fragmentos para esta consulta)';
return [{ json: { chatInput: q.chatInput, sessionId: q.sessionId, consulta: q.consulta, contexto, contexto_texto, n_fragmentos: contexto.length } }];
